 Mapping specification(String suffixLabel){as(author);var product=process.createProduct(new ProcessCommands.ProductCreate("SBOOK"+suffix+suffixLabel,"合成验收制剂","SYNTHETIC",suffixLabel,unit),key());var pkg=process.createPackage(new ProcessCommands.PackageCreate(id(product),"SBP"+suffix+suffixLabel),key());String pid=pkg.path("selectedVersion").path("id").asText();process.saveFormula(pid,new ProcessCommands.FormulaSave(0L,"合成验收固定处方","SBF"+suffix+suffixLabel,"10",unit,List.of(new ProcessCommands.FormulaLine(1,material,"2",unit,"0",true))),null,key());var ops=new ArrayList<ProcessCommands.Operation>();int seq=0;for(String code:List.of("PREPARE","FILL","PACK"))ops.add(new ProcessCommands.Operation(code,code,++seq,null,null,List.of(),null,false,List.of()));process.saveRoute(pid,new ProcessCommands.RouteSave(1L,"合成三工序","SBR"+suffix+suffixLabel,ops),null,key());process.transition(pid,"SUBMIT",new ProcessCommands.Transition(2L,"提交",null),null,key());as(approver);process.transition(pid,"APPROVE",new ProcessCommands.Transition(3L,"独立审批","token"),null,key());process.transition(pid,"PUBLISH",new ProcessCommands.Transition(4L,"发布",null),null,key());var forms=new ArrayList<EbrCommands.Form>();seq=0;for(var op:processQuery.operations(1,Long.parseLong(pid))){var field=new EbrCommands.Field(op.operationCode()+"_ACTUAL",null,"实际记录","TEXT","MANUAL","STRING",null,null,true,false,null,null,"标准取冻结工艺；不默认确认正常",1,null,List.of());forms.add(new EbrCommands.Form("F_"+op.operationCode(),op.operationCode(),op.id(),"1.0",++seq,List.of(field)));}as(author);var template=templates.create(new EbrCommands.Create(pid,"SBT"+suffix+suffixLabel),key());template=templates.save(id(template),new EbrCommands.Save(0L,"合成表单",new EbrCommands.Definition(List.of(),forms,List.of(),List.of(),List.of())),null,key());template=templates.command(id(template),"SUBMIT",new EbrCommands.Command(template.path("versionNo").asLong(),"提交"),null,key());as(approver);template=templates.command(id(template),"APPROVE",new EbrCommands.Command(template.path("versionNo").asLong(),"独立审批"),null,key());template=templates.command(id(template),"PUBLISH",new EbrCommands.Command(template.path("versionNo").asLong(),"发布"),null,key());return new Mapping(id(product),pid,id(template));}
